package br.com.admeclesial.interfaces.web.relatorio;
import br.com.admeclesial.application.relatorio.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@Controller @RequestMapping("/relatorios/pessoas") public class RelatorioPessoaWebController { private final RelatorioPessoaApplicationService service; private final RelatorioContextoService contexto; public RelatorioPessoaWebController(RelatorioPessoaApplicationService s,RelatorioContextoService c){service=s;contexto=c;}
 @GetMapping public String consultar(@RequestParam(required=false) UUID organizacaoUuid,@RequestParam(required=false) String nome,@RequestParam(required=false) Boolean ativo,@RequestParam(defaultValue="0") int pagina,@RequestParam(defaultValue="25") int tamanho,@RequestParam(defaultValue="nome") String ordenacao,@RequestParam(defaultValue="asc") String direcao,Model model){ var orgs=contexto.organizacoesAutorizadas(); model.addAttribute("organizacoes",orgs); model.addAttribute("organizacaoUuid",organizacaoUuid); model.addAttribute("nome",nome); model.addAttribute("ativo",ativo); if(organizacaoUuid!=null)model.addAttribute("resultado",service.consultar(new RelatorioPessoaFiltro(organizacaoUuid,nome,ativo,pagina,tamanho,ordenacao,direcao))); return "relatorio/pessoas"; }
}
